25	import org.springframework.stereotype.Service;
26	
27	import java.time.Instant;
28	import java.time.LocalDate;
29	import java.time.ZoneOffset;
30	import java.util.List;
31	import java.util.Map;
32	
33	/**
34	 * 发证/换发：签发为终态。
35	 * “挂起插入新证 → 旧证置 SUPERSEDED → 新证置 VALID → 检验置 CERTIFIED”全部在
36	 * {@link IdempotentExecutor} 的同一事务内完成；
37	 * uq_certificate_valid 唯一索引 + FOR UPDATE 行锁保证并发下也不会出现两张有效证书。
38	 */
39	@Service
40	public class CertificateService {
41	
42	    private final CertificateRepository certificateRepository;
43	    private final SurveyRepository surveyRepository;
44	    private final ShipRepository shipRepository;
45	    private final DefectRepository defectRepository;
46	    private final IdempotentExecutor executor;
47	
48	    public CertificateService(CertificateRepository certificateRepository,
49	                              SurveyRepository surveyRepository,
50	                              ShipRepository shipRepository,
51	                              DefectRepository defectRepository,
52	                              IdempotentExecutor executor) {
53	        this.certificateRepository = certificateRepository;
54	        this.surveyRepository = surveyRepository;
55	        this.shipRepository = shipRepository;
56	        this.defectRepository = defectRepository;
57	        this.executor = executor;
58	    }
59	
60	    /** 签发/换发证书（幂等；签发终态重复签发返回幂等成功，不产生新版本）。 */
61	    public ApiResult<CertifyResponse> certify(CertifyRequest request) {
62	        Survey survey = surveyRepository.findById(request.surveyId())
63	                .orElseThrow(() -> new NotFoundException("SURVEY_NOT_FOUND",
64	                        "检验不存在: surveyId=" + request.surveyId()));
65	        Ship ship = shipRepository.findById(survey.shipId()).orElseThrow();
66	        String fp = Fingerprint.of(request.requestId(), "CERTIFY",
67	                Map.of("surveyId", request.surveyId()));
68	
69	        return executor.run(request.requestId(), fp, CertifyResponse.class,
70	                () -> doCertify(survey, ship));
71	    }
72	
73	    private CertifyResponse doCertify(Survey survey, Ship ship) {
74	        Instant now = executor.now();
75	        LocalDate today = LocalDate.ofInstant(now, ZoneOffset.UTC);
76	
77	        // 签发终态：重复签发直接返回该检验产生的证书（可能后续已被更新版本替代），不产生新版本。
78	        if (survey.status() == SurveyStatus.CERTIFIED) {
79	            Certificate produced = certificateRepository
80	                    .findVersions(ship.id(), survey.type()).stream()
81	                    .filter(c -> survey.id().equals(c.surveyId()))
82	                    .findFirst()
83	                    .orElseThrow(() -> new ConflictException("CERTIFICATE_MISSING",
84	                            "终态检验缺少证书记录"));
85	            return new CertifyResponse(SurveyResponse.from(survey, ship.imo()),
86	                    CertificateResponse.from(produced, ship.imo()), null);
87	        }
88	        if (survey.status() != SurveyStatus.BOARDED) {
89	            throw new ConflictException("SURVEY_NOT_BOARDED",
90	                    "检验尚未完成登轮，不能发证: surveyId=" + survey.id());
91	        }
92	
93	        List<Defect> defects = defectRepository.findBySurvey(survey.id());
94	        defects.stream()
95	                .filter(d -> d.severity() == DefectSeverity.MAJOR
96	                        && d.status() != DefectStatus.RECTIFIED)
97	                .findFirst()
98	                .ifPresent(d -> {
99	                    throw new BusinessRuleException("MAJOR_DEFECT_OPEN",
100	                            "重大缺陷未整改，不得发证: defectId=" + d.id());
101	                });
102	        defects.stream()
103	                .filter(d -> d.status() == DefectStatus.REJECTED_LATE)
104	                .findFirst()
105	                .ifPresent(d -> {
106	                    throw new BusinessRuleException("DEFECT_OVERDUE",
107	                            "存在逾期未合格复查的缺陷，不得发证: defectId=" + d.id());
108	                });
109	
110	        // 行锁旧有效证书，随后“挂起插入新证 -> 旧证失效 -> 新证生效”同事务完成。
111	        Certificate old = certificateRepository.findValidForUpdate(ship.id(), survey.type())
112	                .orElse(null);
113	        // 拿到行锁后重读检验状态：并发重复发证时，若对方已在锁等待期间完成发证，
114	        // 按终态幂等返回已产生的证书，不再产生新版本。
115	        Survey latest = surveyRepository.findById(survey.id()).orElseThrow();
116	        if (latest.status() == SurveyStatus.CERTIFIED) {
117	            Certificate produced = certificateRepository
118	                    .findVersions(ship.id(), survey.type()).stream()
119	                    .filter(c -> survey.id().equals(c.surveyId()))
120	                    .findFirst()
121	                    .orElseThrow(() -> new ConflictException("CERTIFICATE_MISSING",
122	                            "终态检验缺少证书记录"));
123	            return new CertifyResponse(SurveyResponse.from(latest, ship.imo()),
124	                    CertificateResponse.from(produced, ship.imo()), null);
125	        }
126	        int version = certificateRepository.nextVersion(ship.id(), survey.type());
127	
128	        // 新证有效期照常到下一周期窗口末日；展期只衔接旧证到期与本次发证之间的间隙，
129	        // 不叠加到新证（旧证展期后的 valid_until 作为历史版本保留）。
130	        LocalDate validUntil = baseValidUntil(survey);
131	
132	        Certificate created = certificateRepository.insert(
133	                ship.id(), survey.type(), version,
134	                CertificateStatus.VALID,
135	                today, validUntil, survey.id(), false, now);
136	        try {
137	            if (old != null) {
138	                certificateRepository.markSuperseded(old.id(), created.id());
139	            }
140	            certificateRepository.markValid(created.id());
141	            surveyRepository.markCertified(survey.id(), now);
142	        } catch (org.springframework.dao.DuplicateKeyException e) {
143	            // 并发发证：唯一索引保证只可能有一张有效证书，竞争方落败。
144	            throw new ConflictException("CERTIFY_RACE_LOST",
145	                    "并发发证冲突：该船该检验类型已由另一请求发证");
146	        }
147	
148	        Survey certified = surveyRepository.findById(survey.id()).orElseThrow();
149	        Certificate fresh = certificateRepository.findById(created.id()).orElseThrow();
150	        return new CertifyResponse(SurveyResponse.from(certified, ship.imo()),
151	                CertificateResponse.from(fresh, ship.imo()),
152	                old == null ? null : old.id());
153	    }
154	
155	    /**
156	     * 新证基线有效期至（UTC，含当日）：年度/中间为次年锚点 +3 个月；
157	     * 特别为满 5 年锚点 +3 个月。已批准展期时由调用方叠加展期月数。
158	     */
159	    private LocalDate baseValidUntil(Survey survey) {
160	        return switch (survey.type()) {
161	            case ANNUAL, INTERMEDIATE ->
162	                    survey.cycleAnchor().plusYears(1).plusMonths(3);
163	            case SPECIAL ->
164	                    survey.cycleAnchor().plusYears(5).plusMonths(3);
165	        };
166	    }
167	}
