30	            rs.getLong("id"),
31	            rs.getString("request_id"),
32	            rs.getString("fingerprint"),
33	            rs.getInt("http_status"),
34	            rs.getString("response_body"),
35	            rs.getTimestamp("created_at").toInstant()
36	    );
37	
38	    /** 按 requestId 查询历史记录。 */
39	    public Optional<IdempotentRecord> find(String requestId) {
40	        return jdbc.query("SELECT * FROM idempotent_record WHERE request_id = ?",
41	                        MAPPER, requestId)
42	                .stream().findFirst();
43	    }
44	
45	    /**
46	     * 抢占新 requestId（先占位，业务成功后由 {@link #complete} 回填结果）。
47	     *
48	     * @return true 表示抢占成功（首次）；false 表示键已存在（并发落败或重放）
49	     */
50	    public boolean reserve(String requestId, String fingerprint, Instant now) {
51	        try {
52	            jdbc.update("""
53	                            INSERT INTO idempotent_record
54	                                (request_id, fingerprint, http_status, response_body, created_at)
55	                            VALUES (?, ?, ?, '', ?)
56	                            """,
57	                    requestId, fingerprint, STATUS_PENDING, Timestamp.from(now));
58	            return true;
59	        } catch (DuplicateKeyException e) {
60	            return false;
61	        }
62	    }
63	
64	    /** 业务执行成功后回填首次响应结果。 */
65	    public void complete(String requestId, int httpStatus, String responseBody) {
66	        jdbc.update("UPDATE idempotent_record SET http_status = ?, response_body = ? WHERE request_id = ?",
67	                httpStatus, responseBody, requestId);
68	    }
69	}
