28	 */
29	class ConcurrencyFlowTest extends AbstractH2IntegrationTest {
30	
31	    private static final LocalDate ANNIVERSARY = LocalDate.of(2020, 6, 15);
32	    private static final LocalDate DELIVERY = LocalDate.of(2020, 3, 1);
