39	    private record HttpResult(int status, JsonNode body) {
40	    }
41	
42	    private HttpResult postSync(String path, Object body) {
43	        HttpHeaders headers = new HttpHeaders();
44	        headers.setContentType(MediaType.APPLICATION_JSON);
45	        ResponseEntity<String> response = rest.getRestTemplate()
46	                .postForEntity(url(path), new HttpEntity<>(body, headers), String.class);
47	        try {
48	            return new HttpResult(response.getStatusCode().value(),
49	                    new ObjectMapper().readTree(response.getBody()));
50	        } catch (Exception e) {
51	            throw new IllegalStateException(e);
52	        }
53	    }
54	
55	    private List<HttpResult> runParallel(int n, java.util.function.Supplier<HttpResult> task)
56	            throws Exception {
57	        ExecutorService pool = Executors.newFixedThreadPool(n);
58	        CountDownLatch ready = new CountDownLatch(n);
59	        CountDownLatch start = new CountDownLatch(1);
60	        try {
61	            List<Future<HttpResult>> futures = IntStream.range(0, n).mapToObj(i ->
62	                    pool.submit(() -> {
63	                        ready.countDown();
64	                        assertTrue(start.await(10, TimeUnit.SECONDS));
65	                        return task.get();
66	                    })).toList();
67	            assertTrue(ready.await(10, TimeUnit.SECONDS));
68	            start.countDown();
69	            List<HttpResult> results = new java.util.ArrayList<>();
70	            for (Future<HttpResult> f : futures) {
71	                results.add(f.get(30, TimeUnit.SECONDS));
72	            }
73	            return results;
74	        } finally {
75	            pool.shutdownNow();
76	        }
77	    }
78	
79	    @Test
80	    void parallelApplicationsForSameShipAndTypeOnlyOneAccepted() throws Exception {
81	        registerShip("ship-pa", "IMO-PA");
82	        setClockDate(LocalDate.of(2026, 6, 15));
83	
84	        List<HttpResult> results = runParallel(8, () ->
85	                postSync("/api/surveys",
86	                        applyBody("apply-" + java.util.UUID.randomUUID(),
87	                                "IMO-PA", "ANNUAL")));
88	
89	        long ok = results.stream().filter(r -> r.status == 200).count();
90	        long conflict = results.stream()
91	                .filter(r -> r.status == 409
92	                        && "SURVEY_IN_PROGRESS".equals(r.body.get("code").asText()))
93	                .count();
94	        assertEquals(1, ok, "恰好一个申请受理");
95	        assertEquals(7, conflict, "其余并发申请全部 409");
96	
97	        Integer surveys = jdbc.queryForObject(
98	                "SELECT COUNT(*) FROM survey WHERE ship_id="
99	                        + "(SELECT id FROM ship WHERE imo='IMO-PA')", Integer.class);
100	        assertEquals(1, surveys);
101	        Integer inProgress = jdbc.queryForObject(
102	                "SELECT COUNT(*) FROM survey WHERE ship_id="
103	                        + "(SELECT id FROM ship WHERE imo='IMO-PA') AND active_flag='Y'",
104	                Integer.class);
105	        assertEquals(1, inProgress);
106	    }
