108	    @Test
109	    void parallelSameRequestSameParamsAcceptedOnceOtherReplays() throws Exception {
110	        registerShip("ship-pr", "IMO-PR");
111	        setClockDate(LocalDate.of(2026, 6, 15));
112	
113	        List<HttpResult> results = runParallel(6, () ->
114	                postSync("/api/surveys",
115	                        applyBody("same-key", "IMO-PR", "ANNUAL")));
116	
117	        long first = results.stream().filter(r -> r.status == 200
118	                && !r.body.get("replayed").asBoolean()).count();
119	        long replay = results.stream().filter(r -> r.status == 200
120	                && r.body.get("replayed").asBoolean()).count();
121	        long inFlight = results.stream()
122	                .filter(r -> r.status == 409
123	                        && "IDEMPOTENCY_IN_FLIGHT".equals(r.body.get("code").asText()))
124	                .count();
125	        assertEquals(1, first, "唯一首次受理");
126	        assertEquals(5, replay + inFlight, "其余请求重放首次结果或得到处理中冲突");
127	
128	        Integer surveys = jdbc.queryForObject(
129	                "SELECT COUNT(*) FROM survey WHERE request_id='same-key'", Integer.class);
130	        assertEquals(1, surveys, "同键并发不产生多条检验");
131	        // 处理中冲突的请求随后用同参数重放，必须拿到首次结果。
132	        HttpResult later = postSync("/api/surveys",
133	                applyBody("same-key", "IMO-PR", "ANNUAL"));
134	        assertEquals(200, later.status);
135	        assertTrue(later.body.get("replayed").asBoolean());
136	    }
