152	        long ok = results.stream().filter(r -> r.status == 200).count();
153	        long raceLost = results.stream()
154	                .filter(r -> r.status == 409
155	                        && "CERTIFY_RACE_LOST".equals(r.body.get("code").asText()))
156	                .count();
157	        assertTrue(ok >= 1);
158	        assertEquals(8, ok + raceLost, "不存在 5xx，落败方得到明确 409");
159	
